// Copyright 2026 ReC Sandbox. Scene-referred pipeline, stage S6 (SceneReferredSpec.md).#include "StdAfx.h"#include "SceneReferredExport.h"#include "DriverD3D.h"#include "Common/PostProcess/PostProcess.h"#include "Common/RendererResources.h"#include <CryThreading/IJobManager_JobDelegator.h>// ---------------------------------------------------------------------------------------------// The writer job. One per captured frame, low priority, and it owns its payload: the render// thread copied the pixels out of the staging map before launching it, precisely so that nothing// here touches a D3D resource or a ring slot the GPU is about to reuse.// ---------------------------------------------------------------------------------------------void SceneReferredExportWriteJobEntry(SSceneReferredExportJob*);DECLARE_JOB("SceneReferredExport", TSceneReferredExportJob, SceneReferredExportWriteJobEntry);void SceneReferredExportWriteJobEntry(SSceneReferredExportJob* pJob){	if (!pJob)		return;	pJob->desc.pAttributes = pJob->attributes.empty() ? nullptr : pJob->attributes.data();	pJob->desc.numAttributes = (int)pJob->attributes.size();	WriteEXR(pJob->path.c_str(), pJob->width, pJob->height, pJob->pixels.data(), pJob->width, pJob->desc);	delete pJob;}namespace{//! AP1 -> AP0, row-major. The standard ACES matrix pair; these are the AP1ToXYZ / XYZToAP0 product//! and are fixed by the specification, not tuned. Verified against PyOpenColorIO by//! tools/ocio-bake/verify_matrices.py alongside the ones CommonMath.cfi carries.const float kAP1ToAP0[9] ={	 0.6954522414f,  0.1406786965f,  0.1638690622f,	 0.0447945634f,  0.8596711185f,  0.0955343182f,	-0.0055258826f,  0.0040252103f,  1.0015006723f,};//! AP1 (ACEScg) and AP0 (ACES2065-1) primaries with the ACES white, CIE 1931 xy, in the order the//! EXR `chromaticities` attribute wants: rx ry gx gy bx by wx wy.const float kChromaticitiesAP1[8] = { 0.713f,   0.293f,   0.165f, 0.830f,  0.128f,  0.044f,   0.32168f, 0.33767f };const float kChromaticitiesAP0[8] = { 0.7347f,  0.2653f,  0.0f,   1.0f,    0.0001f, -0.0770f, 0.32168f, 0.33767f };//! Turn whatever the operator typed into a real, existing directory. A relative folder lands//! under the user folder, which is where every other tool in this engine writes; an absolute one//! is taken as given.string ResolveCaptureFolder(const char* szFolder){	string folder = (szFolder && *szFolder) ? szFolder : "CaptureEXR";	folder.replace('\\', '/');	const bool bAbsolute = (folder.size() > 1 && folder[1] == ':') || folder[0] == '/';	if (!bAbsolute)		folder = string("%USER%/") + folder;	CryPathString resolved;	gEnv->pCryPak->AdjustFileName(folder.c_str(), resolved, ICryPak::FLAGS_PATH_REAL | ICryPak::FLAGS_FOR_WRITING);	gEnv->pCryPak->MakeDir(resolved.c_str());	return string(resolved.c_str());}float GetBusParam(const char* szName){	CPostEffectsMgr* pPostMgr = PostEffectMgr();	if (!pPostMgr)		return 0.0f;	CEffectParam* pParam = pPostMgr->GetByName(szName);	return pParam ? pParam->GetParam() : 0.0f;}//! The name a LUT slot is currently holding, or "" when the slot is empty. The texture's name is//! the .cube path ccam uploaded it under, so this is where the ODT/LMT provenance comes from//! without the renderer needing a string channel of its own.string GetLutName(CEffectParam* pId, CEffectParam* pSize){	if (!pId || !pSize || pSize->GetParam() < 2.0f)		return string();	CTexture* pTex = CTexture::GetByID((int)pId->GetParam());	return CTexture::IsTextureExist(pTex) ? string(pTex->GetName()) : string();}} // anonymous namespaceCSceneReferredExport& CSceneReferredExport::Get(){	static CSceneReferredExport s_instance;	return s_instance;}CSceneReferredExport::CSceneReferredExport()	: m_state(eState_Idle)	, m_tap(eSceneReferredExportTap_Graded)	, m_encoding(eSceneReferredExportEncoding_ACES2065)	, m_frameIndex(0)	, m_nextSlot(0)	, m_width(0)	, m_height(0)	, m_pOwner(nullptr)	, m_bTimeStepOverridden(false)	, m_fSavedFixedStep(0.0f)	, m_nSavedJitter(1){}bool CSceneReferredExport::WantsGradedTap() const{	return IsArmed() && m_tap == eSceneReferredExportTap_Graded;}bool CSceneReferredExport::StartSequence(const char* szFolder, const char* szPrefix){	if (IsArmed())	{		CryLogAlways("[EXR] a capture is already running - stop it first (rec_CaptureEXRStop)");		return false;	}	m_folder = ResolveCaptureFolder(szFolder);	m_prefix = (szPrefix && *szPrefix) ? szPrefix : "frame";	// The frame counter belongs to the capture, not to a shared console variable. `capture_frames`	// is written by ManualFrameStep and by CryMovie as well, so two captures in one session there	// continue the same numbering; here every arm starts at zero.	m_frameIndex = 0;	m_nextSlot = 0;	m_tap = clamp_tpl(CRenderer::CV_r_SceneReferredExportTap, 0, 1);	m_encoding = clamp_tpl(CRenderer::CV_r_SceneReferredExportEncoding, 0, 1);	m_state = eState_Sequence;	SetFixedStep(true);	CryLogAlways("[EXR] capture armed: '%s/%s.%%06d.exr'", m_folder.c_str(), m_prefix.c_str());	return true;}bool CSceneReferredExport::RequestSingleFrame(const char* szFolder, const char* szPrefix){	if (IsArmed())	{		CryLogAlways("[EXR] a capture is already running - stop it first (rec_CaptureEXRStop)");		return false;	}	m_folder = ResolveCaptureFolder(szFolder);	m_prefix = (szPrefix && *szPrefix) ? szPrefix : "frame";	// A SINGLE frame numbers consecutively for the whole session, which is the one place this	// differs from a sequence. A sequence is one artefact and starts at zero by definition; single	// frames are taken one at a time while something is being looked at, and re-writing	// frame.000000.exr every time makes the command useless for exactly that.	//	// The counter is a hint, not the answer: the disk is asked. That way a file deleted between	// two captures gets its number back, and files left over from a previous session are not	// silently overwritten - neither of which a counter on its own can know. The key is the	// destination, so switching folder or name starts a fresh scan.	const string key = m_folder + "/" + m_prefix;	if (key != m_singleFrameKey)	{		m_singleFrameKey = key;		m_singleFrameNext = 0;	}	m_frameIndex = FirstFreeIndex(m_folder, m_prefix, m_singleFrameNext);	m_singleFrameNext = m_frameIndex + 1;	m_nextSlot = 0;	m_tap = clamp_tpl(CRenderer::CV_r_SceneReferredExportTap, 0, 1);	m_encoding = clamp_tpl(CRenderer::CV_r_SceneReferredExportEncoding, 0, 1);	m_state = eState_SingleFrame;	// No cadence to fix for one frame, so t_FixedStep is left alone.	return true;}int CSceneReferredExport::FirstFreeIndex(const string& folder, const string& prefix, int nStartAt){	// FLAGS_PATH_REAL: the folder is already an absolute, adjusted path from ResolveCaptureFolder,	// and FLAGS_NEVER_IN_PAK because a capture destination is a disk folder - a name that happens	// to exist inside a .pak must not count as taken.	const int nMax = 1000000;   // the format is %06d; past this the name is not unique anyway	for (int i = max(nStartAt, 0); i < nMax; ++i)	{		string path;		path.Format("%s/%s.%06d.exr", folder.c_str(), prefix.c_str(), i);		if (!gEnv->pCryPak->IsFileExist(path.c_str(), ICryPak::eFileLocation_OnDisk))			return i;	}	return max(nStartAt, 0);}void CSceneReferredExport::Stop(const char* szReason){	if (m_state == eState_Idle)		return;	const int nWritten = m_frameIndex;	m_state = eState_Idle;	SetFixedStep(false);	CryLogAlways("[EXR] capture stopped after %d frame%s%s%s", nWritten, (nWritten == 1) ? "" : "s",	             (szReason && *szReason) ? ": " : "", (szReason && *szReason) ? szReason : "");	// The ring is NOT released here - slots may still have a download in flight, and freeing a	// staging resource that is the target of an unretired GPU copy is the exact bug Bloom.cpp's	// m_bDiffractionReadbackIssued guard exists to avoid. BeginFrame drains and releases.}void CSceneReferredExport::SetFixedStep(bool bEnable){	ICVar* pFixedStep = gEnv->pConsole ? gEnv->pConsole->GetCVar("t_FixedStep") : nullptr;	ICVar* pJitter = gEnv->pConsole ? gEnv->pConsole->GetCVar("r_DepthOfFieldLensModelJitter") : nullptr;	if (bEnable)	{		if (m_bTimeStepOverridden || !pFixedStep)			return;		m_fSavedFixedStep = pFixedStep->GetFVal();		m_nSavedJitter = pJitter ? pJitter->GetIVal() : 1;		const float fStep = max(CRenderer::CV_r_SceneReferredExportFixedStep, 0.0f);		if (fStep > 0.0f)			pFixedStep->Set(fStep);		// Jitter mode 2 freezes the lens model's per-frame tap rotation. A sequence in which every		// frame carries a different sub-pixel dither is not a sequence, it is noise with a picture		// behind it - and it is indistinguishable from TAA ghosting when the result is examined.		if (pJitter)			pJitter->Set(2);		m_bTimeStepOverridden = true;	}	else	{		if (!m_bTimeStepOverridden)			return;		if (pFixedStep)			pFixedStep->Set(m_fSavedFixedStep);		if (pJitter)			pJitter->Set(m_nSavedJitter);		m_bTimeStepOverridden = false;	}}void CSceneReferredExport::ReleaseRing(){	for (int i = 0; i < kRingSize; ++i)	{		if (m_ring[i].bIssued)			return; // a download is still in flight; try again next frame	}	for (int i = 0; i < kRingSize; ++i)	{		if (m_ring[i].jobState.IsRunning())			return; // a writer is still going		m_ring[i].pTex.reset();	}	m_width = m_height = 0;	m_pOwner = nullptr;}void CSceneReferredExport::GatherMetadata(SSceneReferredExportMetadata& out) const{	out.frameIndex = m_frameIndex;	out.renderFrameId = gRenDev ? (int)gRenDev->GetRenderFrameID() : 0;	out.engineTime = gEnv->pTimer ? gEnv->pTimer->GetCurrTime() : 0.0f;	out.fps = (CRenderer::CV_r_SceneReferredExportFixedStep > 0.0f) ? (1.0f / CRenderer::CV_r_SceneReferredExportFixedStep) : 0.0f;	// The number that makes the file's absolute scale recoverable. Everything in this pipeline is	// built on 1.0 = 10 000 cd/m^2, and the pre-exposure destroys that unless the scale it applied	// travels with the frame.	out.exposureScale = gcpRendD3D ? gcpRendD3D->GetSceneReferredExposure() : 1.0f;	out.whiteBalanceK = GetBusParam("Global_User_GradeWBKelvin");	out.whiteBalanceTint = GetBusParam("Global_User_GradeWBTint");	// The camera's own numbers, published by ccam on the same bus. They describe the frame; they	// do not affect it.	out.focalLength = GetBusParam("Global_User_CamFocal");	out.tStop = GetBusParam("Global_User_CamTStop");	out.iso = GetBusParam("Global_User_CamISO");	out.shutterTime = GetBusParam("Global_User_CamShutter");	out.nd = GetBusParam("Global_User_CamND");	out.ev100 = GetBusParam("Global_User_CamEV100");	if (CPostEffectsMgr* pPostMgr = PostEffectMgr())	{		out.cameraName = pPostMgr->GetByNameStr("Global_User_CamName");		out.lensName = pPostMgr->GetByNameStr("Global_User_LensName");		out.odtName = GetLutName(pPostMgr->GetLutODTParam(), pPostMgr->GetLutODTSizeParam());		out.lmtName = GetLutName(pPostMgr->GetLutLMTParam(), pPostMgr->GetLutLMTSizeParam());		const Vec4 slope = pPostMgr->GetByNameVec4("Global_User_GradeSlope");		const Vec4 offset = pPostMgr->GetByNameVec4("Global_User_GradeOffset");		const Vec4 power = pPostMgr->GetByNameVec4("Global_User_GradePower");		const float sat = pPostMgr->GetByNameF("Global_User_GradeSaturation");		// ASC order, ASC names, one line - the same numbers a .cdl carries, so a human reading the		// header can type them into Resolve.		out.cdl.Format("slope %g %g %g / offset %g %g %g / power %g %g %g / sat %g",		               slope.x, slope.y, slope.z, offset.x, offset.y, offset.z,		               power.x, power.y, power.z, sat);	}}CTexture* CSceneReferredExport::BeginFrame(CGraphicsPipeline& pipeline, int width, int height){	ConsumeCompleted();	if (m_state == eState_Idle)	{		ReleaseRing();		return nullptr;	}	// Belt and braces for the m_pOwner claim (research/s8-editor-pipelines.md section 4c item 3):	// the exporter is claimed by the first pipeline that runs while armed, and it must never be a	// preview or a probe bake. The tap's own IsSceneReferredStage(6) gate already keeps them out	// now that it carries the preview gate, but the claim is permanent for the duration of a	// capture and the cost of being sure is one virtual call per frame.	if (!pipeline.IsSceneReferredCapable())		return nullptr;	if (m_pOwner == nullptr)		m_pOwner = &pipeline;	if (m_pOwner != &pipeline)		return nullptr;	if (width <= 0 || height <= 0)		return nullptr;	if ((m_width != 0 && m_width != width) || (m_height != 0 && m_height != height))	{		Stop("the resolution changed under the capture");		return nullptr;	}	m_width = width;	m_height = height;	SRingSlot& slot = m_ring[m_nextSlot];	// The ring has come round to a slot whose download has not been consumed, or whose writer is	// still going. Either way the machine cannot keep up, and the honest response is to stop.	if (slot.bIssued)	{		Stop("the readback fell behind - the GPU has not returned an earlier frame");		return nullptr;	}	if (slot.jobState.IsRunning())	{		Stop("the writer fell behind - the disk cannot keep up with the frame rate");		return nullptr;	}	if (!CTexture::IsTextureExist(slot.pTex))	{		// FT_STAGE_READBACK is what gives the texture a PERSISTENT staging resource, and that is		// what makes a two-phase (issue now, map later) download possible at all. The one-shot		// overload allocates a temporary and Maps immediately, which under D3D11 is a full		// pipeline stall - fine for a screenshot, ruinous at one full-res fp16 frame per frame.		const uint32 flags = FT_NOMIPS | FT_DONT_STREAM | FT_USAGE_RENDERTARGET | FT_STAGE_READBACK;		// Named per pipeline AND per slot: the editor runs more than one CGraphicsPipeline, and		// two of them sharing one texture name is the bug S0 had to fix for the satellite formats.		string name;		name.Format("$SceneReferredExport%d%s", m_nextSlot, pipeline.GetUniqueIdentifierName().c_str());		slot.pTex = CTexture::GetOrCreateRenderTarget(name.c_str(), width, height, Clr_Transparent, eTT_2D, flags, eTF_R16G16B16A16F);		if (!CTexture::IsTextureExist(slot.pTex))		{			slot.pTex.reset();			Stop("could not create the readback target");			return nullptr;		}	}	return slot.pTex;}void CSceneReferredExport::EndFrame(){	if (m_state == eState_Idle)		return;	SRingSlot& slot = m_ring[m_nextSlot];	if (!CTexture::IsTextureExist(slot.pTex))		return;	CDeviceTexture* pDevTex = slot.pTex->GetDevTexture();	if (!pDevTex)	{		Stop("the readback target has no device texture");		return;	}	GatherMetadata(slot.metadata);	// The dot before the frame number is the VFX convention Nuke and Resolve auto-detect as a	// sequence, not the engine's own "%s%06d.%s" (DriverD3D.cpp:1258). Getting it wrong means	// every import is manual.	slot.path.Format("%s/%s.%06d.exr", m_folder.c_str(), m_prefix.c_str(), m_frameIndex);	pDevTex->DownloadToStagingResource(0);	slot.bIssued = true;	slot.fIssueTime = gEnv->pTimer->GetAsyncCurTime();	++m_frameIndex;	m_nextSlot = (m_nextSlot + 1) % kRingSize;	if (m_state == eState_SingleFrame)	{		m_state = eState_Idle;		CryLogAlways("[EXR] single frame requested: '%s'", slot.path.c_str());	}}void CSceneReferredExport::ConsumeCompleted(){	for (int i = 0; i < kRingSize; ++i)	{		if (m_ring[i].bIssued)			ConsumeSlot(m_ring[i]);	}}bool CSceneReferredExport::ConsumeSlot(SRingSlot& slot){	CDeviceTexture* pDevTex = CTexture::IsTextureExist(slot.pTex) ? slot.pTex->GetDevTexture() : nullptr;	if (!pDevTex)	{		slot.bIssued = false;		return false;	}	// Never block. A slot that is not ready simply comes back next frame; the ring is what makes	// that free rather than a dropped frame.	if (!pDevTex->AccessCurrStagingResource(0, false))	{		if ((gEnv->pTimer->GetAsyncCurTime() - slot.fIssueTime) > 5.0f)		{			slot.bIssued = false;			Stop("a staging download did not signal in 5 s");		}		return false;	}	const int width = m_width;	const int height = m_height;	SSceneReferredExportJob* pJob = new SSceneReferredExportJob();	pJob->width = width;	pJob->height = height;	pJob->path = slot.path;	pJob->pixels.resize((size_t)width * (size_t)height * 4);	// The mapped rows are PITCHED, not packed. Assuming width * 8 bytes here is what produces a	// sheared image and an hour of confusion.	const auto copyOut = [width, height, pJob](void* pData, uint32 rowPitch, uint32 slicePitch) -> bool	{		const uint8* pRow = static_cast<const uint8*>(pData);		CryHalf* pDst = pJob->pixels.data();		const size_t rowBytes = (size_t)width * 4 * sizeof(CryHalf);		for (int y = 0; y < height; ++y, pRow += rowPitch, pDst += (size_t)width * 4)			memcpy(pDst, pRow, rowBytes);		return true;	};	pDevTex->AccessCurrStagingResource(0, false, copyOut);	slot.bIssued = false;	// Everything the file will say about itself, decided here on the render thread while the	// camera state that produced these pixels is still the current one.	const bool bAces2065 = (m_encoding == eSceneReferredExportEncoding_ACES2065);	pJob->desc.compression = (EExrCompression)clamp_tpl(CRenderer::CV_r_SceneReferredExportCompression, 0, 4);	pJob->desc.bWriteAlpha = false;	pJob->desc.bChromaticities = true;	memcpy(pJob->desc.chromaticities, bAces2065 ? kChromaticitiesAP0 : kChromaticitiesAP1, sizeof(pJob->desc.chromaticities));	// The container flag is a claim of ST 2065-4 conformance, which is a claim about AP0 data. It	// goes on the AP0 file and never on the AP1 one.	pJob->desc.bAcesImageContainerFlag = bAces2065;	pJob->desc.bColorMatrix = bAces2065;	if (bAces2065)		memcpy(pJob->desc.colorMatrix, kAP1ToAP0, sizeof(pJob->desc.colorMatrix));	const SSceneReferredExportMetadata& md = slot.metadata;	const bool bGraded = (m_tap == eSceneReferredExportTap_Graded);	std::vector<SExrAttribute>& a = pJob->attributes;	a.push_back(SExrAttribute::String("owner", "ReC Sandbox"));	// A T1 file and a T2 file look similar and mean completely different things. Anything reading	// these has to be able to tell them apart without asking a human.	a.push_back(SExrAttribute::String("rec/exportTap", bGraded ? "pre-ODT" : "HDRTarget"));	a.push_back(SExrAttribute::String("rec/workingSpace", bAces2065 ? "ACES2065-1" : "ACEScg"));	a.push_back(SExrAttribute::String("rec/specVersion", "SceneReferredSpec S6"));	a.push_back(SExrAttribute::Int("rec/schemaVersion", 1));	a.push_back(SExrAttribute::Int("rec/frameIndex", md.frameIndex));	a.push_back(SExrAttribute::Int("rec/renderFrameId", md.renderFrameId));	a.push_back(SExrAttribute::Float("rec/engineTime", md.engineTime));	if (md.fps > 0.0f)		a.push_back(SExrAttribute::Float("rec/fps", md.fps));	a.push_back(SExrAttribute::Float("rec/exposureScale", md.exposureScale));	a.push_back(SExrAttribute::Float("rec/whiteBalance_K", md.whiteBalanceK));	a.push_back(SExrAttribute::Float("rec/whiteBalance_tint", md.whiteBalanceTint));	// The exposure triangle. T-stop and not f-number: the T-stop is the control the camera model	// actually has, and `aperture` is the classic attribute name to get wrong, since a	// photographic reading and a projection reading both plausibly claim it.	if (md.focalLength > 0.0f)		a.push_back(SExrAttribute::Float("rec/focalLength_mm", md.focalLength));	if (md.tStop > 0.0f)		a.push_back(SExrAttribute::Float("rec/tStop", md.tStop));	if (md.iso > 0.0f)		a.push_back(SExrAttribute::Float("rec/iso", md.iso));	if (md.shutterTime > 0.0f)	{		a.push_back(SExrAttribute::Float("rec/shutterTime_s", md.shutterTime));		// `expTime` is a standard EXR attribute and readers already understand it, so it goes in		// alongside ours rather than instead of it.		a.push_back(SExrAttribute::Float("expTime", md.shutterTime));	}	a.push_back(SExrAttribute::Float("rec/ndStops", md.nd));	a.push_back(SExrAttribute::Float("rec/ev100", md.ev100));	if (!md.cameraName.empty())		a.push_back(SExrAttribute::String("rec/cameraName", md.cameraName));	if (!md.lensName.empty())		a.push_back(SExrAttribute::String("rec/lensName", md.lensName));	if (!md.odtName.empty())		a.push_back(SExrAttribute::String("rec/odt", md.odtName));	if (!md.lmtName.empty())		a.push_back(SExrAttribute::String("rec/lmt", md.lmtName));	if (!md.cdl.empty())		a.push_back(SExrAttribute::String("rec/cdl", md.cdl));	TSceneReferredExportJob job(pJob);	job.SetPriorityLevel(JobManager::eLowPriority);	job.RegisterJobState(&slot.jobState);	job.Run();	return true;}void CSceneReferredExport::Shutdown(){	m_state = eState_Idle;	SetFixedStep(false);	for (int i = 0; i < kRingSize; ++i)	{		// Blocking is correct exactly here and nowhere else: the job manager and the textures are		// about to go away (DiffractionKernel.cpp:761 is the same ordering).		if (m_ring[i].jobState.IsRunning())			gEnv->GetJobManager()->WaitForJob(m_ring[i].jobState);		m_ring[i].bIssued = false;		m_ring[i].pTex.reset();	}	m_width = m_height = 0;	m_pOwner = nullptr;}